    sha256: 'a11031c095ea2d4f9bc66284598eb2a80efed4f30a64d98b315815006095be8d',
    rawJson:
      '{\n  "id": "n1-grammar-07",\n  "questionType": "GRAMMAR_SELECT",\n  "questionText": "全国大会の決勝戦（　）、選手だけでなく、普段は静かな観客まで声を張り上げて応援する。",\n  "options": [\n    "をおいて",\n    "にかこつけて",\n    "ともなると",\n    "をよそに"\n  ],\n  "correctIndex": 2,\n  "explanationKo": "전국대회 결승전 정도의 특별한 단계가 되면 평소 조용하던 관객까지 열띠게 응원한다는 일반적인 양상을 말하므로 「ともなると」가 맞습니다. 특정 단계·상황에 이르면 나타나는 두드러진 변화를 표현합니다. 유일 후보·구실·개의치 않음은 이 관계가 아닙니다.",\n  "optionRationalesKo": [\n    "をおいて는 보통 다른 후보가 없음을 나타내는 부정 표현 등과 연결하며 결승 단계가 되면 달라지는 반응을 나타내지 않습니다.",\n    "にかこつけて는 어떤 일을 구실로 삼음을 나타내지만 본문은 응원의 핑계나 숨은 목적을 말하지 않습니다.",\n    "ともなるとは 결승전이라는 특별한 단계가 되면 관객 반응까지 달라짐을 나타냅니다.",\n    "をよそには 결승전을 개의치 않는다는 관계인데 결승전 때문에 두드러지는 응원과 맞지 않습니다."\n  ],\n  "learningGoalKo": "특별한 단계에 이르면 나타나는 양상 ともなると를 구별합니다.",\n  "tags": [\n    "특별한 단계",\n    "ともなると",\n    "결승전"\n  ],\n  "draftId": "JLP-255-n1-grammar-07-draft1",\n  "level": "N1",\n  "subject": "GRAMMAR",\n  "difficulty": "NORMAL",\n  "explanationJa": null,\n  "draftStatus": "UNREVIEWED",\n  "reuseExistingDraft": false,\n  "parentVersion": null,\n  "candidateIdOnly": true,\n  "originalityDeclarationKo": "이번 세션 직접 작성 신규 초안입니다. 기존 은행·초안은 중복 점검용이며 실제 JLPT·상업 문항을 복사하지 않았습니다. 외부 권리/교육자 감수 인증은 아닙니다.",\n  "time": {\n    "startedAt": "2026-10-07T07:03:34.250698+00:00",\n    "completedAt": "2026-10-07T07:03:52.301537+00:00",\n    "elapsedSeconds": 18.050839,\n    "basis": "작성·파일화 벽시간; 사전산정/검수시간 아님"\n  },\n  "usage": {\n    "inputTokens": null,\n    "outputTokens": null,\n    "reason": "문항별 원값 미제공; 추정하지 않음"\n  }\n}'
