    sha256: 'd0f407361b584c9d42ee0f8245b9f7e47593da5404e66d7bdc4d71c6a6869ade',
    rawJson:
      '{\n  "id": "n5-vocabulary-14",\n  "draftId": "JLP-318-n5-vocabulary-14-draft2",\n  "level": "N5",\n  "subject": "VOCABULARY",\n  "questionType": "ORTHOGRAPHY",\n  "questionText": "「せんせい」を かんじで かくと どれですか。",\n  "options": [\n    "先正",\n    "先生",\n    "千生",\n    "先性"\n  ],\n  "correctIndex": 1,\n  "tags": [\n    "한자 표기"\n  ],\n  "explanationKo": "せんせい의 한자 표기는 先生입니다. 先과 生을 차례대로 씁니다.",\n  "optionRationalesKo": [\n    "둘째 글자가 正으로 바뀌어 先生의 표기가 아닙니다.",\n    "先生이 せんせい의 올바른 표기입니다.",\n    "첫째 글자가 千으로 바뀌어 先生의 표기가 아닙니다.",\n    "둘째 글자가 性으로 바뀌어 先生의 표기가 아닙니다."\n  ],\n  "learningGoalKo": "先生의 한자 표기를 모양·음이 비슷한 잘못된 글자 조합과 구별합니다.",\n  "difficulty": "NORMAL",\n  "explanationJa": null,\n  "draftStatus": "UNREVIEWED",\n  "reuseExistingDraft": true,\n  "parentVersion": {\n    "file": "/Users/doji/Desktop/docs/ai/jlpt-office/JLPT/hive/agents/jim-murolp98/evidence/jlp-318/n5-vocabulary-14-draft1.json",\n    "sha256": "1677591f9852a416b2b04b550f2e3da2560fdae1318558bb33cd4b65c80b48a6"\n  },\n  "candidateIdOnly": true,\n  "originalityDeclarationKo": "이번 세션 직접 작성 신규 초안입니다. 실제 JLPT·상업 문항을 복사하지 않았으며 외부 권리/교육자 감수 인증은 아닙니다.",\n  "time": {\n    "elapsedSeconds": null,\n    "basis": "문항별 전체 작성시간 미기록; 묶음 실제시간 별도 manifest"\n  },\n  "usage": {\n    "inputTokens": null,\n    "outputTokens": null,\n    "reason": "문항별 원값 미제공; 추정하지 않음"\n  },\n  "revisionTime": {\n    "startedAt": "2026-10-07T10:21:06.693967+00:00",\n    "completedAt": "2026-10-07T10:21:06.694445+00:00",\n    "elapsedSeconds": 0.000478,\n    "basis": "두 조사 교체 실행 시간만; 앞선 QA 읽기·구성 시간 제외"\n  }\n}'
