    sha256: '13a1ccef01de0267670d65d600781a2f46f23532b25693a60ccc6f470b98ae29',
    rawJson:
      '{\n  "questionType": "KANJI_READING",\n  "questionText": "班の 仕事を 最後まで 確かめる「責任」が、私には あります。「責任」の 読み方は どれですか。",\n  "options": ["せきねん", "せっきにん", "せきじん", "せきにん"],\n  "correctIndex": 3,\n  "explanationKo": "맡은 일을 마지막까지 확인할 책임을 나타내는 責任은 せきにん으로 읽습니다. 責은 せき, 任은 이 단어에서 にん이며 중간에 작은 っ를 넣지 않습니다.",\n  "optionRationalesKo": [\n    "任을 이 숙어에서 ねん으로 읽지 않습니다.",\n    "責任의 독음에는 작은 っ가 들어가지 않습니다.",\n    "任을 이 숙어에서 じん으로 읽지 않습니다.",\n    "責任의 올바른 독음은 せきにん입니다."\n  ],\n  "learningGoalKo": "의무를 나타내는 추상 명사 責任의 숙어 독음을 구별합니다.",\n  "tags": ["한자 읽기", "추상 명사"],\n  "priorComparisonKo": "기존 N3어휘06 感謝·11 表情·정적01 影響와 목표 단어는 다르지만 숙어 읽기와 소리 혼동 판별을 재사용합니다. 승인된 N1문법13에는 責任者, N1독해09에는 責任이 등장하므로 責任의 최초 노출로 세지 않습니다.",\n  "id": "n3-vocabulary-16",\n  "draftId": "JLP-477-next-n3-vocabulary-16-draft1",\n  "level": "N3",\n  "subject": "VOCABULARY",\n  "difficulty": "NORMAL",\n  "passage": null,\n  "explanationJa": null,\n  "draftStatus": "UNREVIEWED",\n  "candidateIdOnly": true,\n  "reuseExistingDraft": false,\n  "parentVersion": null,\n  "originalityDeclarationKo": "현재 배정에서 직접 작성한 원본 후보입니다. 승인 원본·정적 seed는 중복·태그 대조에, 원 출판사의 사전 항목은 독음·뜻 확인에 사용했습니다. 실제 JLPT·상업 문항·사전의 완성 예문을 복제하지 않았으며 외부 권리·교육 감수 인증은 아닙니다.",\n  "time": {\n    "startedAt": null,\n    "completedAt": null,\n    "elapsedSeconds": null,\n    "basis": "문항별 생성 시간을 계측하지 않았습니다. 묶음 실제 착수는 start.json에 기록했습니다."\n  },\n  "usage": {\n    "inputTokens": null,\n    "outputTokens": null,\n    "reason": "문항별 실측 원값이 없어 추정하지 않습니다."\n  }\n}\n'
