    sha256: '608dba0184ea8b15f3252ea93762b9e5ec4445c4974a6d22ce0d6d77c2007fc0',
    rawJson:
      '{\n  "id": "n5-grammar-24",\n  "questionType": "GRAMMAR_SELECT",\n  "questionText": "友だちを さそう文になるように、空欄に 入るものを 選んでください。A「あした、いっしょに 公園を 散歩（　）。」B「いいですね。いっしょに 行きましょう。」",\n  "passage": null,\n  "options": ["しました", "して", "しましょう", "しませんでした"],\n  "correctIndex": 2,\n  "tags": ["권유", "동사 활용"],\n  "learningGoalKo": "함께 행동하자는 권유를 나타내는 ましょう를 구별합니다.",\n  "explanationKo": "내일 친구에게 함께 공원을 산책하자고 권합니다. 散歩します의 ます를 ましょう로 바꿔 散歩しましょう라고 합니다. B도 좋다며 함께 가자고 답합니다. 과거 긍정·과거 부정은 내일의 권유와 맞지 않으며, して만으로는 이 문장의 정중한 권유형을 이루지 못합니다.",\n  "optionRationalesKo": [\n    "しました는 과거에 산책했다는 형태입니다. 내일 함께 산책하자는 권유가 아닙니다.",\n    "して는 て형입니다. 제시된 문장에서는 정중한 권유를 나타내는 しましょう가 필요합니다.",\n    "しましょう는 함께 하자는 권유입니다. 내일의 산책 제안과 B의 응답에 맞습니다.",\n    "しませんでした는 과거에 산책하지 않았다는 형태입니다. 내일의 권유와 맞지 않습니다."\n  ],\n  "priorComparisonKo": "정적 N5-03 見ませんか와 초대/권유 기능이 같습니다. 이번에는 질문형 초대가 아니라 ましょう로 함께 하자는 제안을 구성합니다. 동행·권유 상위 기능은 복습입니다.",\n  "difficultyObservationKo": "권유하라는 지시와 내일이라는 시점을 함께 제시했습니다. 내부 N5/NORMAL이며 실제 학습 난이도는 확인하지 않았습니다.",\n  "targetForm": "ましょう",\n  "grammarFactIds": ["invitation-mashou"],\n  "draftId": "JLP-477-next-n5-grammar-24-draft1",\n  "level": "N5",\n  "subject": "GRAMMAR",\n  "difficulty": "NORMAL",\n  "explanationJa": null,\n  "draftStatus": "UNREVIEWED",\n  "candidateIdOnly": true,\n  "reuseExistingDraft": false,\n  "parentVersion": null,\n  "originalityDeclarationKo": "현재 배정에서 일본어 문항·보기·한국어 해설을 직접 작성했습니다. 이전 원본과 정적 seed는 중복/태그 대조, 공개 언어 자료는 문법 사실 확인용입니다. 실제 JLPT·상업 문항·공개 자료의 예문을 복사하지 않았으며 외부 권리·교육 감수 인증은 아닙니다.",\n  "time": {\n    "startedAt": null,\n    "completedAt": null,\n    "elapsedSeconds": null,\n    "basis": "문항별 시각은 미계측입니다. 실제 묶음 착수는 start.json에 기록했습니다."\n  },\n  "usage": {\n    "inputTokens": null,\n    "outputTokens": null,\n    "reason": "문항별 실측 원값이 없어 추정하지 않습니다."\n  }\n}\n'
