    sha256: '252e98be68bf59bfba3e42fbcb95440a1c2f035ad003a4caa181c9b815ef600d',
    rawJson:
      '{\n  "id": "n4-vocabulary-21",\n  "draftId": "JLP-477-next-n4-vocabulary-21-draft1",\n  "level": "N4",\n  "subject": "VOCABULARY",\n  "questionType": "KANJI_READING",\n  "difficulty": "NORMAL",\n  "questionText": "会社で、新しい 商品について 話し合う「会議」が あります。「会議」の 読み方は どれですか。",\n  "passage": null,\n  "options": ["かいき", "かいぎ", "がいぎ", "かぎ"],\n  "correctIndex": 1,\n  "tags": ["한자 읽기"],\n  "learningGoalKo": "会議의 숙어 독음 かいぎ를 탁음과 음절이 다른 보기에서 구별합니다.",\n  "explanationKo": "여러 사람이 새 상품에 관해 의논하는 회의라는 뜻의 会議는 かいぎ라고 읽습니다. 이 단어에서 会는 かい, 議는 ぎ이며 정답은 두 번째 보기입니다. 한자의 모든 용법을 이 읽기 하나로 한정하는 설명은 아닙니다.",\n  "optionRationalesKo": [\n    "かいき는 마지막 음절이 청음 き입니다. 会議의 마지막 음절은 탁음 ぎ입니다.",\n    "かいぎ가 会議의 올바른 숙어 독음입니다.",\n    "がいぎ는 첫 음절을 が로 바꾼 보기입니다. 会議의 첫 음절은 か입니다.",\n    "かぎ는 会議의 かい 부분에서 い를 빠뜨린 보기입니다. 会議는 かいぎ로 읽습니다."\n  ],\n  "targetWord": "会議",\n  "priorComparisonKo": "기존N4 독음 親切/便利/工場 및 정적予定와 숙어 독음 판별 기능이 같습니다. 업무의 모임이라는 맥락과 표적만 바뀐 복습이며 새 판별 기능으로 세지 않습니다.",\n  "difficultyObservationKo": "내부 N4/NORMAL로 작성 중입니다. 공식 JLPT 어휘 급수와 실제 학습 난도는 미확인입니다.",\n  "dictionaryFactIds": ["kaigi"],\n  "explanationJa": null,\n  "draftStatus": "UNREVIEWED",\n  "candidateIdOnly": true,\n  "reuseExistingDraft": false,\n  "parentVersion": null,\n  "originalityDeclarationKo": "이 배정에서 일본어 문항·보기·한국어 해설을 직접 썼습니다. 사전은 읽기·뜻 확인용이며 예문·실제JLPT·상업 문항을 복사하지 않았습니다. 외부 권리·전문 감수 인증은 아닙니다.",\n  "time": {\n    "startedAt": null,\n    "completedAt": null,\n    "elapsedSeconds": null,\n    "basis": "묶음 실제 착수만 start.json에 기록했고 문항별 시간은 미계측입니다."\n  },\n  "usage": {\n    "inputTokens": null,\n    "outputTokens": null,\n    "reason": "문항별 실측 원값을 추정하지 않습니다."\n  }\n}\n'
