    sha256: '6a21dda13cb1fd7177fe784823f4dcbbbb32cb459b8c8ad33334329a65973443',
    rawJson:
      '{\n  "id": "n4-vocabulary-24",\n  "draftId": "JLP-477-next-n4-vocabulary-24-draft1",\n  "level": "N4",\n  "subject": "VOCABULARY",\n  "questionType": "ORTHOGRAPHY",\n  "difficulty": "NORMAL",\n  "questionText": "図書館で 本を 借りる 方法を、係の 人が「せつめい」してくれました。「せつめい」の 正しい 漢字表記は どれですか。",\n  "passage": null,\n  "options": ["発明", "証明", "説明", "会議"],\n  "correctIndex": 2,\n  "tags": ["한자 표기"],\n  "learningGoalKo": "절차를 알려 주는 せつめい의 한자 표기 説明을 독음이 다른 発明·証明·会議와 구별합니다.",\n  "explanationKo": "방법을 이해할 수 있도록 설명하는 せつめい의 표기는 説明입니다. 発明은 はつめい, 証明은 しょうめい, 会議는 かいぎ로 읽으며 제시된 せつめい의 표기가 아닙니다. 説明과 証明은 일부 관련 뜻이 있어도 같은 읽기나 동일 단어로 취급하지 않습니다.",\n  "optionRationalesKo": [\n    "発明은 はつめい로 읽으며 새 방법이나 물건을 고안한다는 뜻 등이 있습니다. せつめい의 표기가 아닙니다.",\n    "証明은 しょうめい로 읽으며 근거로 사실이나 판단을 밝힌다는 뜻 등이 있습니다. 説明과 독음이 다릅니다.",\n    "説明은 せつめい로 읽으며 책을 빌리는 방법을 이해하도록 알려 준다는 문맥과 맞습니다.",\n    "会議는 かいぎ로 읽는 회의입니다. 이 묶음21번의 표적이기도 하지만 せつめい의 표기는 아닙니다."\n  ],\n  "targetWord": "説明",\n  "priorComparisonKo": "기존 N4 片付ける/選ぶ/予約와 한자 표기 판별 기능이 같습니다. 説明은 기존 문항에도 등장하고 会議는 이번21의 표적을 오답으로 다시 쓰므로 최초노출이나 새 기능으로 세지 않습니다.",\n  "difficultyObservationKo": "내부 N4/NORMAL입니다. 明 공유 보기와 다른 독음의 구별이며, 오답 단어의 실제 학습 범위·공식급수·실측난도는 미확인입니다.",\n  "dictionaryFactIds": ["setsumei", "hatsumei", "shomei", "kaigi"],\n  "explanationJa": null,\n  "draftStatus": "UNREVIEWED",\n  "candidateIdOnly": true,\n  "reuseExistingDraft": false,\n  "parentVersion": null,\n  "originalityDeclarationKo": "이 배정에서 일본어 문항·보기·한국어 해설을 직접 썼습니다. 사전은 읽기·뜻 확인용이며 예문·실제JLPT·상업 문항을 복사하지 않았습니다. 외부 권리·전문 감수 인증은 아닙니다.",\n  "time": {\n    "startedAt": null,\n    "completedAt": null,\n    "elapsedSeconds": null,\n    "basis": "원래 묶음 착수는 start.json, 실제 재개는 resume-start.json에 기록했고 문항별 시간은 미계측입니다."\n  },\n  "usage": {\n    "inputTokens": null,\n    "outputTokens": null,\n    "reason": "문항별 실측 원값을 추정하지 않습니다."\n  }\n}\n'
